correctedCode:
#include <stdio.h>

struct Point {
    int x, y;
};

int main() {
    struct Point a = {1, 2};
    struct Point b = {1, 2};
    if (a.x == b.x && a.y == b.y) {
        printf("Equal\n");
    } else {
        printf("Not equal\n");
    }
    return 0;
}
